// The backfill's brief and its apply: a rule's events are read from the carrier's own
// history (born where it first appears, reworded where its text changed), a commit that
// touched many packs is a sweep - listed, never drafted onto an element - and apply
// appends every drafted entry once, refusing the whole brief on one bad entry.
const commitAs = (root, message, { email = 't@t' } = {}) => {
  git(root, 'add', '-A');
  execFileSync('git', ['-c', `user.email=${email}`, '-c', 'user.name=t', 'commit', '-q', '-m', message], { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
};
const briefRepo = () => {
  const root = repo({
    ...FILES,
    'packs/alpha/provenance/doing-thing.md': '',
    'packs/alpha/provenance/doing-another.md': '',
    'packs/alpha/pack.mjs': '// alpha: the pack for doing things.
//
// No fingerprint: a thing is declared.

export default {
  version: 2,
};
',
    'packs/alpha/RULES.md': '- **Doing a thing** — the settled way. (doing-thing)

- **Doing another** — plainly. (doing-another)
',
    'packs/alpha/provenance/VERSIONS.md': '| Version | Date | What changed |
|---|---|---|
| 2 | 2026-08-02 | Said better (#8) |
| 1 | 2026-07-01 | seed (#7) |
',
  });
  writeFileSync(join(root, 'packs/alpha/RULES.md'), '- **Doing a thing** — the settled way, said better. (doing-thing)

- **Doing another** — plainly. (doing-another)
');
  commitAs(root, 'Said better (#8)

The old wording hid the point.

Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>
Claude-Session: https://example.invalid/s', { email: '1+tester@users.noreply.github.com' });
  for (const p of ['beta', 'gamma', 'delta', 'epsilon']) {
    mkdirSync(join(root, `packs/${p}`), { recursive: true });
    writeFileSync(join(root, `packs/${p}/RULES.md`), '- **Elsewhere** — so.
');
  }
  writeFileSync(join(root, 'packs/alpha/RULES.md'), '- **Doing a thing** - the settled way, said better. (doing-thing)

- **Doing another** - plainly. (doing-another)

- **Born in a sweep** - so. (born-in-sweep)
');
  writeFileSync(join(root, 'packs/alpha/provenance/born-in-sweep.md'), '');
  commitAs(root, 'Hyphens everywhere (#9)');
  mkdirSync(join(root, 'packs/alpha/skills/doing-it'), { recursive: true });
  writeFileSync(join(root, 'packs/alpha/skills/doing-it/SKILL.md'), '---
name: doing-it
description: Do it. Use when doing it.
metadata:
  body: workflow
---

1. Do it.
');
  writeFileSync(join(root, 'packs/alpha/provenance/doing-it.md'), '');
  commitAs(root, 'A skill for doing it (#10)');
  writeFileSync(join(root, 'packs/alpha/pack.mjs'), '// alpha: the pack for doing things.
//
// No fingerprint: a thing is declared.

export default {
  version: 3,
};
');
  commitAs(root, 'Bump pack versions: alpha 3 (#11)');
  writeFileSync(join(root, 'packs/alpha/pack.mjs'), '// alpha: the pack for doing things.
//
// No fingerprint: a thing is declared.

export default {
  version: 3,
  hidden: true,
};
');
  commitAs(root, 'Hide alpha (#12)');
  return root;
};

test('brief reads each element's events from its carrier's history, sets a sweep aside, and drafts entries from the commit', async () => {
  const root = briefRepo();
  try {
    const { code, out } = await capture(['brief', 'alpha'], root);
    assert.equal(code, 0);
    assert.match(out, /5 empty files · 4 pack-local commits · 1 sweep/);
    assert.match(out, /```entry born-in-sweep
## 2026-\d{2}-\d{2} · born · Hyphens everywhere \(#9\)/, 'the element a sweep bore is born there all the same');
    assert.match(out, /## sweeps[\s\S]*#9/, 'the five-pack commit is a sweep');
    assert.doesNotMatch(out, /```entry doing-thing
## \d{4}-\d{2}-\d{2} · reworded · Hyphens/, 'a sweep is never drafted onto an element');
    assert.match(out, /```entry doing-thing
## 2026-\d{2}-\d{2} · born · seed \(#7\)/);
    assert.match(out, /```entry-defaults
- \*\*Actor:\*\* @tester\.
- \*\*Model:\*\* Claude Opus 5, per the commit trailer\.
- \*\*Landed:\*\* #8 · pack version 2\.
```
```entry doing-thing
## 2026-\d{2}-\d{2} · reworded · Said better \(#8\)
```/, 'the commit's shared fields are written once, ahead of its entries');
    assert.doesNotMatch(out, /## PR #11/, 'a commit that only bumped the version is no event');
    assert.match(out, /```entry doing-another
## 2026-\d{2}-\d{2} · born · seed \(#7\)[\s\S]*?- \*\*Mechanism:\*\* a RULES\.md rule, triggered on "Doing another"/);
    assert.doesNotMatch(out, /```entry doing-another
## [^
]* · reworded/, 'a rule whose text never changed has one event');
    assert.match(out, /```entry doing-it
## 2026-\d{2}-\d{2} · born · A skill for doing it \(#10\)/);
    assert.match(out, /## PR #8 · [^
]*Said better[\s\S]*?> The old wording hid the point\./, 'the body is quoted once, under its pull request');
    assert.doesNotMatch(out, /Claude-Session/, 'trailers are stripped');
    assert.match(out, /- It was split from beta until #99 folded it back\./);
    assert.match(out, /## the manifest, packs/alpha/pack\.mjs
[^
]*
> alpha: the pack for doing things\.
>
> No fingerprint: a thing is declared\.
- #12 \d{4}-\d{2}-\d{2} Hide alpha
/, 'the header comment is quoted and the manifest's later commits are listed, the bump left out');
    assert.match(out, /```entry _pack
## 2026-\d{2}-\d{2} · born · seed \(#7\)/);
    assert.doesNotMatch(out, /```entry _pack
## [^
]* · reworded/, '_pack drafts its birth only');
  } finally { removeTree(root); }
});

